insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-sum-of-two-values', 'Sum of Two Values', 'CSES', 'https://cses.fi/problemset/task/1640', 1100, 'Given $n$ numbers and target $x$, find two distinct indices whose values sum to $x$.', 'The first line contains two integers $n$ and $x$.

The second line contains $n$ integers $a_1,\dots,a_n$.', 'Print any two positions whose values sum to $x$, or `IMPOSSIBLE`.', '$1 \le n \le 2 \times 10^5$', '[{"input":"4 8\n2 7 5 1","output":"2 4"}]'::jsonb, 'O(N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-sum-of-two-values-a1', 'cses-sum-of-two-values', 'Hash map of complements', ARRAY['Ad-Hoc']::text[], ARRAY['Sorting']::text[], ARRAY['Hash Map']::text[], ARRAY['Store value → index while scanning','Look up x - a_i']::text[], 'One pass with a hash map from value to index. For each $a_i$, check if $x-a_i$ was seen.');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-sum-of-two-values-a2', 'cses-sum-of-two-values', 'Sort + two pointers', ARRAY['Two Pointers']::text[], ARRAY['Sorting']::text[], ARRAY['1D Array']::text[], ARRAY['Keep original indices when sorting','Move left/right based on sum vs x']::text[], 'Sort pairs $(value, index)$ and use two pointers to find a pair summing to $x$.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-movie-festival', 'Movie Festival', 'CSES', 'https://cses.fi/problemset/task/1629', 1100, 'In a movie festival, $n$ movies will be shown. You know the starting and ending time of each movie. What is the maximum number of movies you can watch entirely? You can watch a movie only if its start is $\ge$ the previous movie''s end.', 'The first line contains an integer $n$.

Then $n$ lines follow, each with two integers $a$ and $b$: the start and end time of a movie.', 'Print the maximum number of movies you can watch entirely.', '$1 \le n \le 2 \times 10^5$', '[{"input":"3\n3 5\n4 9\n5 8","output":"2"}]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-movie-festival-a1', 'cses-movie-festival', 'Sort by ending time', ARRAY['Greedy']::text[], ARRAY['Sorting']::text[], ARRAY['1D Array']::text[], ARRAY['Sort by end time instead of start time','Always take the next movie that finishes earliest among feasible ones']::text[], 'Classic activity selection: sort intervals by ending time and greedily pick the next compatible movie.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-restaurant-customers', 'Restaurant Customers', 'CSES', 'https://cses.fi/problemset/task/1619', 1100, 'You are given the arrival and leaving times of $n$ customers in a restaurant. What was the maximum number of customers simultaneously present?', 'The first line contains an integer $n$.

Then $n$ lines follow, each with two integers $a$ and $b$: arrival and leaving times.', 'Print the maximum number of customers present at the same time.', '$1 \le n \le 2 \times 10^5$', '[{"input":"3\n5 8\n2 4\n3 9","output":"2"}]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-restaurant-customers-a1', 'cses-restaurant-customers', 'Sweep line events', ARRAY['Greedy','Ad-Hoc']::text[], ARRAY['Sorting']::text[], ARRAY['1D Array']::text[], ARRAY['Turn each customer into +1 at arrival and -1 at departure','Process events in time order; track running sum']::text[], 'Create $2n$ events (arrive / leave), sort by time (leave before arrive on ties if needed), and scan while maintaining the current occupancy.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-dice-combinations', 'Dice Combinations', 'CSES', 'https://cses.fi/problemset/task/1633', 1100, 'Your task is to count the number of ways to construct sum $n$ by throwing a dice one or more times. Each throw gives an integer between $1$ and $6$. Order matters. Print the answer modulo $10^9+7$.', 'The only input line contains an integer $n$.', 'Print the number of ways to construct sum $n$, modulo $10^9+7$.', '$1 \le n \le 10^6$', '[{"input":"3","output":"4"}]'::jsonb, 'O(N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-dice-combinations-a1', 'cses-dice-combinations', '1D DP recurrence', ARRAY['Dynamic Programming']::text[], ARRAY['Knapsack']::text[], ARRAY['1D Array']::text[], ARRAY['$dp[x] = \sum_{f=1}^{6} dp[x-f]$','Order of throws matters so this is permutations, not combinations']::text[], 'Let $dp[x]$ be ways to form sum $x$. Transition by the last face. Base $dp[0]=1$. Compute up to $n$ modulo $10^9+7$.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-removing-digits', 'Removing Digits', 'CSES', 'https://cses.fi/problemset/task/1637', 1100, 'You are given an integer $n$. On each step you may subtract one of the digits of the current number. How many steps are needed to go from $n$ down to $0$?', 'The only input line contains an integer $n$.', 'Print the minimum number of steps to reach $0$.', '$1 \le n \le 10^6$', '[{"input":"27","output":"5"}]'::jsonb, 'O(N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-removing-digits-a1', 'cses-removing-digits', 'DP over values', ARRAY['Dynamic Programming']::text[], ARRAY[]::text[], ARRAY['1D Array']::text[], ARRAY['$dp[x] = 1 + \min_{\text{digit } d \text{ of } x} dp[x-d]$','Greedy always subtract largest digit is not always optimal to prove casually — DP is safe']::text[], 'Compute $dp[0..n]$ bottom-up. For each $x$, try subtracting each digit appearing in the decimal representation of $x$.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cf-1849b', 'Lamps', 'Codeforces', 'https://codeforces.com/problemset/problem/1849/B', 1100, 'There are $n$ monsters with health $h_i$. Each attack you choose one living monster and deal $k$ damage. After each of your attacks, the fight continues until all are dead. You always attack; monsters do not damage you in this problem — you simply must output the order in which monsters die if you always attack a living monster maximizing $h \bmod k$ (if $h\bmod k=0$ treat as $k$), breaking ties by preferring larger remaining health pattern of the editorial: sort by $(h_i-1)\bmod k$ descending.', 'The first line contains $t$.

Each test: first line $n$ and $k$ ($1 \le n \le 2\cdot 10^5$, $1 \le k \le 10^9$); second line $h_1\dots h_n$ ($1 \le h_i \le 10^9$). Sum of $n$ $\le 2\cdot 10^5$.', 'For each test print $n$ indices (1-based) — the order monsters are killed.', '$1 \le \sum n \le 2\cdot 10^5$', '[{"input":"3\n3 5\n1 2 3\n5 1\n1 1 1 1 1\n4 2\n1 4 4 1","output":"3 2 1\n1 2 3 4 5\n2 3 1 4"}]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cf-1849b-a1', 'cf-1849b', 'Sort by remainder', ARRAY['Greedy']::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY['Kill order by largest (h-1)%k']::text[], 'Priority is the damage needed beyond full k-hits; sort and print indices.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('mineira-2019-b-podando-galhos', 'Podando Galhos', 'Maratona Mineira', 'https://github.com/gcmgomes/mineira2019', 1100, 'O natal já passou. Porém, por causa da correria do dia-a-dia, a árvore de natal na casa de Graça continua montada.
Mas a família dessa garota-prodígio decidiu fazer um mutirão no próximo fim de semana para desmontar a árvore,
onde também ainda está a toca do coelhinho da páscoa.

Como Ada, a mãe de Graça, é uma cientista da computação apaixonada pelo que faz,
ela nunca perde uma oportunidade de introduzir a filha
no fabuloso mundo dos algoritmos e estruturas de dados.
Por isso, a árvore de natal da família foi realmente montada como uma árvore
que você encontraria em um curso de algoritmos: ela possui bolas numeradas de $1$ a $N$, cada uma
podendo ser vista como um vértice, pendurada a outra bola acima dela,
com exceção da raiz que foi pendurada no teto.

Para que o desmonte da árvore seja mais divertido, Ada propôs um desafio a Graça.
No $i$-ésimo segundo do desmonte, Ada irá cortar o fio que originalmente mantinha a bola de número $B_i$ suspensa.
Caso a bola ainda esteja suspensa, ela irá então cair ao chão, juntamente com todas as bolas que estavam
penduradas nela direta ou indiretamente.
Pode acontecer que Ada corte o fio de uma bola que já esteja no chão - neste caso, nada acontece.
Passados $N$ segundos, com todas as bolas no chão, Ada pergunta a Graça em qual segundo cada uma das $N$
bolas caiu.
Caso Graça acerte todos os números, ela será recompensada com uma viagem para assistir a próxima
edição da Maratona Mineira, onde ela poderá conhecer outras jovens mentes promissoras como a sua!

Graça é muito ágil e conseguiu anotar todos os números necessários manualmente. Mas será que você
consegue fazer um programa para ajudá-la a se preparar para o desmonte de árvore de natal do ano que vem?
Considere que as bolas caem imediatamente ao chão quando deixam de estar presas direta ou indiretamente ao teto.

### Entrada

A primeira linha da entrada contém um inteiro $N$, o número de bolas da árvore de natal.
A segunda linha contém $N$ inteiros $P_1, , P_N$ separados por espaço.
$P_i$ indica que há um fio prendendo a bola $i$ à bola $P_i$, que está acima na árvore.
$P_i = -1$ indica que a bola $i$ é a raiz da árvore.
Há sempre exatamente uma bola $i$ com 
$P_i = -1$, e é garantido que as ligações dadas descrevem uma árvore.
A última linha contém $N$ inteiros $B_1, , B_N$ separados por espaço, indicando qual fio é
cortado no $i$-ésimo segundo do processo de desmonte.
Cada inteiro entre $1$ e $N$ aparece exatamente uma vez na última linha da entrada.

### Saída

Escreva na saída uma linha com $N$ inteiros separados por espaço.
O $i$-ésimo desses inteiros deve indicar em qual segundo a bola $i$ cai ao chão.

### Restrições

- $1 ≤ N ≤ 2 × 10^5$

### Exemplos', 'See statement.', 'See statement.', '1 ≤ N ≤ 2 × 10^5$', '[]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('mineira-2019-b-podando-galhos-a1', 'mineira-2019-b-podando-galhos', 'VIII Maratona Mineira — standard', ARRAY['Graph Algorithms','Geometry','Math / Number Theory']::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY['VIII Maratona Mineira (2019), problem B. Auto-tagged from statement; refine after solving.']::text[], 'From VIII Maratona Mineira. Review tags and write a proper editorial after solving.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('mineira-2022-b-festa-laser', 'Festa Laser', 'Maratona Mineira', 'https://github.com/gcmgomes/mineira2022', 1100, '% To add an image or include a .tex file you need to add
% 
% to the relative (to the main document) path.
%
% Example:
% 

Maria Joaquina, ou pela alcunha Majô, é uma jovem muito criativa e interessada em ciência. Desde criança, ela aprendeu que o conhecimento racional que a humanidade adquiriu ao longo da história permitiu com que a qualidade de vida melhorasse, e que descobertas ainda maiores fossem feitas. “Coitado dos negacionistas!”, sempre diz ela.

Um dos feitos mais inspiradores para Majô foi a expedição à Lua de 1969, resultado da cooperação de matemáticos, engenheiros e cientistas de várias áreas do conhecimento. Após muito trabalho, o foguete Apollo 11 da NASA levou astronautas de uma base na Terra por uma viagem de 8 dias, com partes muito críticas, como a decolagem, a aproximação e pousos lunares, a operação do módulo lunar, e a reentrada na atmosfera terrestre.

Nessa viagem, os astronautas Michael Collins, Buzz Aldrin e Neil Armstrong  deixaram um arranjo de espelhos no solo lunar, capaz de refletir raios lasers emitidos a partir do planeta Terra. Quando soube disso, Majô imediatamente começou a montar o equipamento apropriado em seu quintal e chamou todos os seus vizinhos para acompanharem o experimento durante a festa que ela titulou ``AFE – Avoid Flat Earthers''''.

Além de conversar sobre astronomia, Majô, amante do estoicismo, também conversará com os convidados sobre outros avanços da humanidade, como o pensamento filosófico, o método científico e as vacinas. Entretanto, para sua surpresa, ela descobriu que vários vizinhos não acreditam na chegada da humanidade à Lua ou em algum avanço da ciência, e vão só causar transtornos em sua festa laser.

Para evitar a fadiga, a jovem Joaquina pediu que você escreva um programa que indica se uma pessoa deve ser cortada do evento, por ser negacionista (``Óbvio, né gente!'''', como diz Majô). Neste programa, o vizinho deve informar se ele é negacionista ou não. Se for um pessoa sensata, com certeza será convidada.

### Entrada

A entrada possui uma linha contendo um valor inteiro $V$, que vale $1$, quando o vizinho analisado é negacionista, e $0$ caso contrário.

### Saída

A saída possui uma linha com um valor inteiro $A$, que vale $1$ quando o vizinho deve ser convidado por Majô para a festa AFE, de acordo com o critério que ela adota, e $0$ caso contrário.

### Restrições

	
- $0 ≤ V ≤ 1$.

### Exemplos', 'See statement.', 'See statement.', '0 ≤ V ≤ 1$', '[]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('mineira-2022-b-festa-laser-a1', 'mineira-2022-b-festa-laser', 'IX Maratona Mineira — standard', ARRAY['Dynamic Programming','Geometry','Math / Number Theory']::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY['IX Maratona Mineira (2022), problem B. Auto-tagged from statement; refine after solving.']::text[], 'From IX Maratona Mineira. Review tags and write a proper editorial after solving.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('mineira-2023-b-contorno', 'Contorno', 'Maratona Mineira', 'https://github.com/gcmgomes/mineira2023', 1100, '% To add an image or include a .tex file you need to add
% 
% to the relative (to the main document) path.
%
% Example:
% 

A Avenida do Contorno é uma avenida circular de Belo Horizonte. Durante sua construção, foram instalados vários estabelecimentos ao longo dela, como várias drogarias (Araújo), várias pastelarias (Rei do Pastel), etc. Por motivos logísticos, todo par de estabelecimentos do mesmo tipo deve ser conectado diretamente por uma rua (que pode passar por dentro ou por fora da Contorno).

Porém, para que a Contorno continue sendo a avenida principal, não podem existir esquinas em outros lugares da cidade (cruzamento de ruas). Além disso, não haverá túneis ou viadutos na cidade.

Dados os tipos de estabelecimentos que existem em ordem ao longo da Contorno, sua tarefa é determinar se é possível construir as ruas conectando todo par de estabelecimentos de mesmo tipo, sem criar esquinas (cruzamentos de ruas) extras.

%
% For input, use one of the following
%

### Entrada

A primeira linha contém um inteiro $1 ≤ N ≤ 10^3$. A segunda linha contém $N$ inteiros $1 ≤ c_i ≤ N$, em que $c_i$ representa o tipo do $i$-ésimo estabelecimento em ordem na Contorno.

%
% For output, use one of the following
%

### Saída

Imprima  S caso seja posssível construir as estradas, e  N caso contrário.

### Restrições

- $1 ≤ N ≤ 10^3$.

% will look for files named sample-n.in and sample-n.sol (where n is 1, 2, 3...)
%in the documents directory and include them as samples.', 'See statement.', 'See statement.', '1 ≤ N ≤ 10^3$; 1 ≤ c_i ≤ N$, em que $c_i$ representa o tipo; 1 ≤ N ≤ 10^3$', '[]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('mineira-2023-b-contorno-a1', 'mineira-2023-b-contorno', 'X Maratona Mineira — standard', ARRAY['Graph Algorithms','Geometry','Math / Number Theory']::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY['X Maratona Mineira (2023), problem B. Auto-tagged from statement; refine after solving.']::text[], 'From X Maratona Mineira. Review tags and write a proper editorial after solving.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('mineira-2025-b-bares', 'Bares', 'Maratona Mineira', 'https://mineira.sbc.org.br/wp-content/uploads/2025/06/contest.rbx_.pdf', 1100, 'Problema B. Bares

Luffy é um entusiasta de suco de laranja, porém ele já gastou toda a sua mesada e não consegue
comprar nenhum copo. Para satisfazer sua paixão, mesmo sem dinheiro, ele foi para a Rua Sapucaí.

A Rua Sapucaí é famosa por sua grande quantidade de bares, sendo composta por uma sequência
deles de maneira que Luffy consegue ir do i-ésimo bar ao j-ésimo bar em |i−j| segundos. Os clientes
desses bares têm a tradição de comemorar boas notícias comprando uma rodada de suco de laranja
para todos que estão no mesmo bar naquele segundo. Luffy conhece muito bem os clientes, então
sabe exatamente em qual bar xi e em qual segundo ti cada rodada de suco vai ocorrer.

Ajude-o a calcular o número máximo de sucos de laranja que ele pode beber, se ele escolher onde
ele vai começar e andar de maneira ótima. Luffy não precisa parar no bar para beber o suco, pois
sabe andar e beber ao mesmo tempo.

Entrada
A primeira linha da entrada contém um inteiro N (1 ≤ N ≤ 106 ), o número de rodadas de suco. As
próximas N linhas contêm pares de inteiros: na i-ésima delas, xi (0 ≤ xi ≤ 106 ) e ti (0 ≤ ti ≤ 106 ),
indicando que uma rodada de suco ocorrerá no bar xi no segundo ti . É garantido que não ocorrem
duas rodadas em um mesmo bar no mesmo segundo.

Saída
A saída deve conter um único inteiro, o número máximo de sucos de laranja que Luffy pode beber.

Exemplos
 Exemplo de entrada 1                               Exemplo de saída 1
 3                                                  3
 1 0
 0 1
 1 2

 Exemplo de entrada 2                               Exemplo de saída 2
 4                                                  3
 0 1
 1 0
 2 2
 3 3

Explicação do exemplo 2

Luffy consegue participar de até 3 rodadas na ordem: (1, 0), (2, 2), (3, 3).', 'See statement.', 'See statement.', '1 ≤ N ≤ 106 ), o número de rodadas de suco; 0 ≤ xi ≤ 106 ) e ti (0 ≤ ti ≤ 106 ),', '[]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('mineira-2025-b-bares-a1', 'mineira-2025-b-bares', 'XII Maratona Mineira — standard', ARRAY['Math / Number Theory']::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY['XII Maratona Mineira (2025), problem B. Auto-tagged from statement; refine after solving.']::text[], 'From XII Maratona Mineira. Review tags and write a proper editorial after solving.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('mineira-2026-b-bario-world', 'Bário World', 'Maratona Mineira', 'https://mineira.sbc.org.br/wp-content/uploads/2026/06/MMP2026-Prova.pdf', 1100, 'Problema B. Bário World
                                          It’s-a-Me, Bário!

Por conta de suas divertidas mecânicas, Super Bário World é um sucesso entre os gamers mineiros.
No jogo, Bário se move em fases compostas por N blocos, cada um podendo ser sólido ou um buraco
e o objetivo do jogo é chegar do início da fase (o bloco 1) até o final (o bloco N ) sem cair em nenhum
buraco. Bário pode correr sobre os blocos sólidos e, para evitar os buracos, Bário pode pulá-los.

Bário usa botas que têm uma reserva de energia, que inicialmente é 1. Ao correr ele carrega as
botas para poder pular mais longe – cada bloco sobre o qual Bário corre adiciona uma unidade de
carga a seu equipamento. Um pulo de carga v faz com que Bário vá do bloco b para qualquer bloco
entre b + 1 e b + v; ao aterrissar, Bário perde energia de suas botas, retornando ao valor inicial de 1.

Calcule o número mínimo de pulos para Bário chegar na posição N ou indique que é impossível.

Entrada
A primeira linha contém um inteiro T (1 → T → 5 ↑ 105 ) o número de casos de teste (é garantido
que o somatório dos valores de N é menor que 5 ↑ 105 ).

Depois disso seguem T pares de linhas. A primeira linha contém N (2 → N → 5↑105 ), o comprimento
da fase, e a segunda contém uma string de N caracteres representando os blocos da fase, x se for
um bloco sólido e . se for um buraco (é garantido que os blocos 1 e N são sólidos).

Saída
Imprima o número mínimo de pulos para Bário chegar no fim da fase ou ↓1 se não for possível.

Exemplos

 Exemplo de entrada 1                                Exemplo de saída 1
 2                                                   2
 16                                                  -1
 xxxxxxx.xxxx.x.x
 3
 x.x

Explicação do exemplo 1

No primeiro caso de teste, uma possível solução com apenas dois pulos envolve Bário:
  • Correr da posição 1 até a posição 5, carregando as botas com energia 5 e dar um pulo
    aterrisando na posição 9. Ao aterrisar suas botas voltam a ter energia 1.
  • Correr da posição 9 até a posição 12 carregando as botas com energia 4 e pular para o fim.

XIII', 'See statement.', 'See statement.', 'See statement.', '[]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('mineira-2026-b-bario-world-a1', 'mineira-2026-b-bario-world', 'XIII Maratona Mineira — standard', ARRAY['String Algorithms','Math / Number Theory']::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY['XIII Maratona Mineira (2026), problem B. Auto-tagged from statement; refine after solving.']::text[], 'From XIII Maratona Mineira. Review tags and write a proper editorial after solving.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('minas-2025-b-fibo-uai-trem-so', 'Fibo UAI, TREM, SO!', 'Minas de Minas', 'https://mineira.sbc.org.br/wp-content/uploads/2026/11/m3-2025-caderno-maratona.pdf', 1100, 'Problema B. Fibo UAI, TREM, SO!
O pessoal das Minas de Minas resolveu brincar com a famosa sequência de Fibonacci. Mas, como
um bom mineiro não perde a chance de deixar tudo com a sua marca registrada, nasceu a sequência
Fibo UAI, TREM SO!.

Funciona assim: a gente começa como na sequência de Fibonacci tradicional, com 1, 1, e cada novo
número é a soma dos dois anteriores. Até aí, nenhuma novidade. O detalhe mineiro aparece quando
o número cresce tanto que passa a ter mais dígitos do que o número anterior. Nesse momento, em
vez de escrever o número, a gente solta uma palavra bem mineira, seguindo este ciclo:

UAI → TREM → SO → UAI → TREM → SO → · · ·

Ou seja:   sempre que aumentar o número de dígitos, em vez do número aparece uma dessas
palavrinhas, na ordem indicada, repetindo para sempre.

Só que tem outro detalhe: quando a palavra aparece pela primeira vez, ela não vale a soma de
Fibonacci. Ela passa a valer um número xo especial:

      O primeiro UAI vale 10;

      O primeiro TREM vale 100;

      O primeiro SO vale 1000;

      O segundo UAI vale 10000;

      E assim por diante, sempre multiplicando por 10 a cada nova palavra do ciclo.

Esses valores substituem o número de Fibonacci na sequência interna, ou seja, os próximos termos
passam a ser calculados usando também esses valores especiais.

Entrada
                                                  3
A entrada contém um único inteiro N (2 ≤ N ≤ 10 ), indicando a quantidade de termos a imprimir.

Saída
Os N primeiros termos da sequência, separados por um espaço.

Exemplos
 Entrada                                        Saída
 7                                              1 1 2 3 5 8 UAI

 Entrada                                        Saída
 17                                             1 1 2 3 5 8 UAI 18 28 46 74 TREM 174
                                                274 448 722 SO

                                                                                                  5', 'See statement.', 'See statement.', '2 ≤ N ≤ 10 ), indicando a quantidade de term', '[]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('minas-2025-b-fibo-uai-trem-so-a1', 'minas-2025-b-fibo-uai-trem-so', '1ª Maratona Minas de Minas — standard', ARRAY['String Algorithms','Math / Number Theory']::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY['1ª Maratona Minas de Minas (2025), problem B. Auto-tagged from statement; refine after solving.']::text[], 'From 1ª Maratona Minas de Minas. Review tags and write a proper editorial after solving.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('minas-meia-2025-b-distancias-em-minas', 'Distâncias em Minas', 'Minas de Minas', 'https://mineira.sbc.org.br/wp-content/uploads/2026/11/m3-2025-caderno-meia-maratona.pdf', 1100, 'Problema B. Distâncias em Minas
João é um turista que está explorando Minas Gerais e deseja conhecer várias cidades históricas, como
Belo Horizonte, Ouro Preto, Tiradentes e Diamantina. Durante a viagem, ele anotou a distância
percorrida em quilômetros a cada dia, já que adora registrar suas aventuras.

Agora, João quer calcular a distância total percorrida para contar aos amigos o quanto rodou pelas
estradas mineiras.

Escreva um programa que, dado o número de dias da viagem e as distâncias percorridas em cada
um deles, calcule a distância total. Além disso, João gostaria de saber se conseguiu percorrer mais
de 500 km no total  nesse caso, ele vai considerar que fez uma "grande viagem"!

Entrada
A primeira linha contém um número inteiro N (1 ≤ N ≤ 100), representando a quantidade de dias
da viagem. Cada uma das próximas N linhas contém um número inteiro, que representa a distância
percorrida em cada dia (em quilômetros).

Saída
Seu programa deve imprimir duas linhas: Na primeira linha, um número inteiro representando a
distância total percorrida durante a viagem e, na linha seguinte, a mensagem "Grande viagem" se
o total for maior que 500 km, ou "Viagem curta" caso contrário.

Exemplos
 Entrada                                        Saída
 5                                              410
 100                                            Viagem curta
 120
 80
 50
 60

 Entrada                                        Saída
 4                                              520
 200                                            Grande viagem
 150
 100
 70

                                                                                              5', 'See statement.', 'See statement.', '1 ≤ N ≤ 100), representando a quantidade de ', '[]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('minas-meia-2025-b-distancias-em-minas-a1', 'minas-meia-2025-b-distancias-em-minas', '1ª Meia Maratona Minas de Minas — standard', ARRAY['Graph Algorithms','Math / Number Theory']::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY['1ª Meia Maratona Minas de Minas (2025), problem B. Auto-tagged from statement; refine after solving.']::text[], 'From 1ª Meia Maratona Minas de Minas. Review tags and write a proper editorial after solving.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cf-1360c', 'Similar Pairs', 'Codeforces', 'https://codeforces.com/problemset/problem/1360/C', 1200, 'You are given an array of $n$ distinct integers. Pair them into $n/2$ pairs such that each pair consists of two numbers of the same parity, or two numbers differing by $1$.', 'The first line contains an integer $t$ (test cases).

Each test case: an integer $n$, then a line with $n$ integers.', 'For each test case print `YES` or `NO`.', '$2 \le n \le 50$, $n$ even; $T$ test cases', '[{"input":"1\n4\n1 5 3 4","output":"YES"}]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cf-1360c-a1', 'cf-1360c', 'Parity counts + adjacent check', ARRAY['Greedy','Ad-Hoc','Math / Number Theory']::text[], ARRAY['Sorting']::text[], ARRAY['1D Array']::text[], ARRAY['Even counts of odd and even → always yes','Otherwise need one pair with difference 1']::text[], 'If both parity counts are even, pair within parity. Else sort and check for a consecutive pair with difference 1.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cf-489b', 'BerSU Ball', 'Codeforces', 'https://codeforces.com/problemset/problem/489/B', 1200, 'Pair boys and girls so that skill difference is at most $1$. Maximize the number of pairs.', 'The first line contains $n$, then a line with $n$ boy skills.

Then $m$, then a line with $m$ girl skills.', 'Print the maximum number of pairs.', '$1 \le n,m \le 100$', '[{"input":"4\n1 4 6 2\n5\n5 1 5 7 9","output":"3"}]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cf-489b-a1', 'cf-489b', 'Sort + greedy two pointers', ARRAY['Greedy','Two Pointers']::text[], ARRAY['Sorting']::text[], ARRAY['1D Array']::text[], ARRAY['Sort both skill arrays','Greedily match closest feasible partners']::text[], 'Sort both arrays and scan with two pointers, pairing when $|a-b|\le 1$.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-maximum-subarray-sum', 'Maximum Subarray Sum', 'CSES', 'https://cses.fi/problemset/task/1643', 1200, 'Given an array of $n$ integers, find a contiguous subarray with the maximum possible sum.', 'The first line contains an integer $n$.

The second line contains $n$ integers $a_1,\dots,a_n$.', 'Print the maximum subarray sum.', '$1 \le n \le 2 \times 10^5$', '[{"input":"8\n-1 3 -2 5 3 -5 2 2","output":"9"}]'::jsonb, 'O(N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-maximum-subarray-sum-a1', 'cses-maximum-subarray-sum', 'Kadane', ARRAY['Dynamic Programming','Greedy']::text[], ARRAY['Prefix Sums']::text[], ARRAY['1D Array']::text[], ARRAY['Track best ending here vs restart','Handle all-negative arrays carefully']::text[], 'Kadane: maintain current sum, reset when negative (or keep running max for the all-negative case).');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-stick-lengths', 'Stick Lengths', 'CSES', 'https://cses.fi/problemset/task/1074', 1200, 'You have $n$ sticks with lengths $p_i$. Change any stick to any positive length; cost is the absolute difference. Minimize total cost to make all sticks equal.', 'The first line contains an integer $n$.

The second line contains $n$ integers $p_1,\dots,p_n$.', 'Print the minimum total cost to make all sticks equal.', '$1 \le n \le 2 \times 10^5$', '[{"input":"5\n2 3 1 5 2","output":"5"}]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-stick-lengths-a1', 'cses-stick-lengths', 'Median target', ARRAY['Greedy','Math / Number Theory']::text[], ARRAY['Sorting']::text[], ARRAY['1D Array']::text[], ARRAY['Optimal equal length is the median','Mean is wrong for L1 absolute cost']::text[], 'Sort and set every stick to the median length; sum absolute deviations.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-message-route', 'Message Route', 'CSES', 'https://cses.fi/problemset/task/1667', 1200, 'Syrjälä''s network has $n$ computers and $m$ connections. What is the minimum number of computers on a route from computer $1$ to computer $n$? Also reconstruct one such route.', 'The first line contains two integers $n$ and $m$: the number of computers and connections.

Then $m$ lines follow, each with two integers $a$ and $b$: an undirected connection.', 'If a route exists, print two lines: the number of computers on the shortest route, then the computers on one such route from $1$ to $n$. Otherwise print `IMPOSSIBLE`.', '$1 \le n \le 10^5$, $1 \le m \le 2 \times 10^5$', '[{"input":"5 5\n1 2\n1 3\n1 4\n2 3\n5 4","output":"3\n1 4 5"}]'::jsonb, 'O(N + M)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-message-route-a1', 'cses-message-route', 'BFS + parent pointers', ARRAY['Graph Algorithms']::text[], ARRAY['BFS']::text[], ARRAY['Queue','Adjacency List']::text[], ARRAY['Unweighted shortest path → BFS','Store parent[v] to reconstruct the path']::text[], 'Run BFS from $1$. If $n$ is reached, walk parents back to $1$ and reverse the path. Otherwise print IMPOSSIBLE.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('atc-dp-knapsack1', 'Knapsack 1', 'AtCoder', 'https://atcoder.jp/contests/dp/tasks/dp_d', 1200, 'There are $N$ items with weight $w_i$ and value $v_i$. Choose a subset with total weight $\le W$ maximizing total value. Each item at most once.', 'The first line contains two integers $N$ and $W$.

Then $N$ lines follow with $w_i$ and $v_i$.', 'Print the maximum total value with weight at most $W$.', '$1 \le N \le 100$, $1 \le W \le 10^5$', '[{"input":"3 8\n3 30\n4 50\n5 60","output":"90"}]'::jsonb, 'O(N · W)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('atc-dp-knapsack1-a1', 'atc-dp-knapsack1', '0/1 knapsack DP', ARRAY['Dynamic Programming']::text[], ARRAY['Knapsack']::text[], ARRAY['1D Array']::text[], ARRAY['State is (item index, remaining capacity) or rolling 1D weight','Iterate weights backwards to save space']::text[], 'Standard 0/1 knapsack. $dp[w] = \max(dp[w], dp[w-w_i]+v_i)$ processed per item from high $w$ to low.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-towers', 'Towers', 'CSES', 'https://cses.fi/problemset/task/1073', 1200, 'You are given $n$ cubes in order. Process them one by one: place each cube on top of a tower so that it sits on a strictly larger cube, or start a new tower. What is the minimum number of towers?', 'The first line contains an integer $n$.

The second line contains $n$ integers: the cube sizes in processing order.', 'Print the minimum number of towers.', '$1 \le n \le 2 \times 10^5$', '[{"input":"5\n3 8 2 1 5","output":"2"}]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-towers-a1', 'cses-towers', 'Multiset of tops / patience sorting', ARRAY['Greedy']::text[], ARRAY['Binary Search','LIS']::text[], ARRAY['Ordered Set']::text[], ARRAY['Always place on the tower with the smallest top that is still $> cube$','Equivalent to length of longest non-decreasing subsequence intuition']::text[], 'Maintain the sorted tops of towers in a multiset. For each cube, upper_bound the first top strictly greater and replace it; else create a new tower.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-subarray-sums-i', 'Subarray Sums I', 'CSES', 'https://cses.fi/problemset/task/1660', 1200, 'Given an array of $n$ positive integers, count the number of contiguous subarrays whose sum equals $x$.', 'The first line contains two integers $n$ and $x$.

The second line contains $n$ positive integers $a_1,\dots,a_n$.', 'Print the number of contiguous subarrays whose sum equals $x$.', '$1 \le n \le 2 \times 10^5$, $1 \le x \le 10^{18}$', '[{"input":"5 7\n2 4 1 2 7","output":"3"}]'::jsonb, 'O(N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-subarray-sums-i-a1', 'cses-subarray-sums-i', 'Two pointers on positive array', ARRAY['Two Pointers']::text[], ARRAY['Prefix Sums']::text[], ARRAY['1D Array']::text[], ARRAY['All $a_i > 0$ ⇒ window sum is monotone as right advances','Advance left while sum $> x$']::text[], 'Maintain a sliding window. Expand right; shrink left while the sum exceeds $x$; count when sum equals $x$.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-counting-divisors', 'Counting Divisors', 'CSES', 'https://cses.fi/problemset/task/1713', 1200, 'Given $n$ integers, your task is to report for each integer the number of its divisors.

For example, if $x=18$, the correct answer is $6$ because its divisors are $1,2,3,6,9,18$.

Input

The first input line has an integer $n$: the number of integers.

After this, there are $n$ lines, each containing an integer $x$.

Output

For each integer, print the number of its divisors.

Constraints

- $1 ≤ n ≤ 10^5$

- $1 ≤ x ≤ 10^6$

Example

Input:

3
16
17
18

Output:

5
2
6', 'The first input line has an integer $n$: the number of integers.

After this, there are $n$ lines, each containing an integer $x$.', 'For each integer, print the number of its divisors.', '- $1 ≤ n ≤ 10^5$

- $1 ≤ x ≤ 10^6$', '[{"input":"The first input line has an integer $n$: the number of integers.\n\nAfter this, there are $n$ lines, each containing an integer $x$.","output":"For each integer, print the number of its divisors."},{"input":":\n\n3\n16\n17\n18","output":":"}]'::jsonb, 'O(N · X)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-counting-divisors-a1', 'cses-counting-divisors', 'Sieve divisor counts', ARRAY['Math / Number Theory']::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY['Precompute divisor counts with a linear sieve / loop multiples']::text[], 'For i in 1..MAX, add 1 to every multiple; answer queries in O(1).');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-exponentiation', 'Exponentiation', 'CSES', 'https://cses.fi/problemset/task/1095', 1200, 'Your task is to efficiently calculate values $a^b$ modulo $10^9+7$.

Note that in this task we assume that $0^0=1$.

Input

The first input line contains an integer $n$: the number of calculations.

After this, there are $n$ lines, each containing two integers $a$ and $b$.

Output

Print each value $a^b$ modulo $10^9+7$.

Constraints

- $1 ≤ n ≤ 2 \cdot 10^5$

- $0 ≤ a,b ≤ 10^9$

Example

Input:

3
3 4
2 8
123 123

Output:

81
256
921450052', 'The first input line contains an integer $n$: the number of calculations.

After this, there are $n$ lines, each containing two integers $a$ and $b$.', 'Print each value $a^b$ modulo $10^9+7$.', '- $1 ≤ n ≤ 2 \cdot 10^5$

- $0 ≤ a,b ≤ 10^9$', '[{"input":"The first input line contains an integer $n$: the number of calculations.\n\nAfter this, there are $n$ lines, each containing two integers $a$ and $b$.","output":"Print each value $a^b$ modulo $10^9+7$."},{"input":":\n\n3\n3 4\n2 8\n123 123","output":":"}]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-exponentiation-a1', 'cses-exponentiation', 'Modpow', ARRAY['Math / Number Theory']::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY['Binary exponentiation modulo 1e9+7']::text[], 'Compute a^b mod MOD with repeated squaring for each query.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('atc-dp-vacation', 'Vacation', 'AtCoder', 'https://atcoder.jp/contests/dp/tasks/dp_c', 1200, 'Score : 100 points

Problem Statement

Taro''s summer vacation starts tomorrow, and he has decided to make plans for it now.

The vacation consists of N days.
For each i (1 ≤q i ≤q N), Taro will choose one of the following activities and do it on the i-th day:

- A: Swim in the sea. Gain a_i points of happiness.

- B: Catch bugs in the mountains. Gain b_i points of happiness.

- C: Do homework at home. Gain c_i points of happiness.

As Taro gets bored easily, he cannot do the same activities for two or more consecutive days.

Find the maximum possible total points of happiness that Taro gains.

Constraints

- All values in input are integers.

- 1 ≤q N ≤q 10^5

- 1 ≤q a_i, b_i, c_i ≤q 10^4

Input

Input is given from Standard Input in the following format:

N
a_1 b_1 c_1
a_2 b_2 c_2
:
a_N b_N c_N

Output

Print the maximum possible total points of happiness that Taro gains.

Sample Input 1

3
10 40 70
20 50 80
30 60 90

Sample Output 1

210

If Taro does activities in the order C, B, C, he will gain 70 + 50 + 90 = 210 points of happiness.

Sample Input 2

1
100 10 1

Sample Output 2

100

Sample Input 3

7
6 7 8
8 8 3
2 5 2
7 8 6
4 6 8
2 3 4
7 5 1

Sample Output 3

46

Taro should do activities in the order C, A, B, A, C, B, A.', 'Input is given from Standard Input in the following format:

N
a_1 b_1 c_1
a_2 b_2 c_2
:
a_N b_N c_N', 'Print the maximum possible total points of happiness that Taro gains.', '- All values in input are integers.

- 1 ≤q N ≤q 10^5

- 1 ≤q a_i, b_i, c_i ≤q 10^4', '[{"input":"1\n\n3\n10 40 70\n20 50 80\n30 60 90","output":"1"},{"input":"2\n\n1\n100 10 1","output":"2"},{"input":"3\n\n7\n6 7 8\n8 8 3\n2 5 2\n7 8 6\n4 6 8\n2 3 4\n7 5 1","output":"3"}]'::jsonb, 'O(N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('atc-dp-vacation-a1', 'atc-dp-vacation', 'Daily activity DP', ARRAY['Dynamic Programming']::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY['dp[day][activity] with no two consecutive same activities']::text[], 'Maximize happiness with the constraint that the same activity is never chosen two days in a row.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('atc-dp-grid1', 'Grid 1', 'AtCoder', 'https://atcoder.jp/contests/dp/tasks/dp_h', 1200, 'Score : 100 points

Problem Statement

There is a grid with H horizontal rows and W vertical columns.
Let (i, j) denote the square at the i-th row from the top and the j-th column from the left.

For each i and j (1 ≤q i ≤q H, 1 ≤q j ≤q W), Square (i, j) is described by a character a_{i, j}.
If a_{i, j} is ., Square (i, j) is an empty square; if a_{i, j} is #, Square (i, j) is a wall square.
It is guaranteed that Squares (1, 1) and (H, W) are empty squares.

Taro will start from Square (1, 1) and reach (H, W) by repeatedly moving right or down to an adjacent empty square.

Find the number of Taro''s paths from Square (1, 1) to (H, W).
As the answer can be extremely large, find the count modulo 10^9 + 7.

Constraints

- H and W are integers.

- 2 ≤q H, W ≤q 1000

- a_{i, j} is . or #.

- Squares (1, 1) and (H, W) are empty squares.

Input

Input is given from Standard Input in the following format:

H W
a_{1, 1}\ldotsa_{1, W}
:
a_{H, 1}\ldotsa_{H, W}

Output

Print the number of Taro''s paths from Square (1, 1) to (H, W), modulo 10^9 + 7.

Sample Input 1

3 4
...#
.#..
....

Sample Output 1

3

There are three paths as follows:

Sample Input 2

5 2
..
#.
..
.#
..

Sample Output 2

0

There may be no paths.

Sample Input 3

