insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('uva-558', 'Wormholes', 'UVA', 'https://onlinejudge.org/external/5/558.pdf', 1500, 'In a spacetime with $n$ stars and $m$ wormholes (directed edges that may have negative time cost), decide whether there is a negative cycle (you can go back in time indefinitely).', 'Multiple tests. Each: $n\ m$ then $m$ triples $x\ y\ t$ (edge $x\to y$ cost $t$).', 'Print `possible` if a negative cycle exists, else `not possible`.', '$1 \le n \le 1000$, $1 \le m \le 2000$', '[{"input":"3 3\n0 1 1000\n1 2 15\n2 1 -42","output":"possible"}]'::jsonb, 'O(N · M)');
