insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('poj-1860', 'Currency Exchange', 'POJ', 'http://poj.org/problem?id=1860', 1700, 'There are $N$ currencies and $M$ exchange points. Each point trades $A\leftrightarrow B$ with rates and commissions. Starting with currency $S$ and amount $V$, can you increase your money by a sequence of exchanges?', 'N M S V, then M lines of exchange parameters.', 'Print `YES` or `NO`.', '$N \le 100$', '[]'::jsonb, 'O(N · M)');
