insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('atc-abc184-f', 'Programming Contest', 'AtCoder', 'https://atcoder.jp/contests/abc184/tasks/abc184_f', 1800, 'You have $n$ problems with times $a_i$ and limit $T$. Maximize total time of a subset that does not exceed $T$.', 'n T and the array a.', 'Print the maximum feasible sum.', '$1 \le n \le 40$', '[]'::jsonb, 'O(N)');
